 function costText(t){const plan=t.planRequests||0;if(t.requests&&plan===t.requests)return 'ChatGPT plan';if(t.requests&&(!t.apiReported||t.apiReported===t.unpriced))return 'Unpriced'+(plan?' + plan':'');return money(t.cost)+(t.unpriced||t.missing?' + unpriced':'')+(plan?' + plan':'');}
 function calendar(year){const first=new Date(year,0,1,12),last=new Date(year,11,31,12),start=new Date(first);start.setDate(start.getDate()-start.getDay());const days=[];for(let date=new Date(start);date<=last||date.getDay()!==0;date.setDate(date.getDate()+1)){days.push({key:dateKey(date),date:new Date(date),inYear:date.getFullYear()===year});if(days.length>378)break;}return days;}
 window.YCAtlasUsage={aggregate,calendar,dateKey};
 if(!$('usage-dialog'))return;
 let snapshot=null,selectedYear=new Date().getFullYear(),refreshTimer=null,focused=null,loadVersion=0;
 const text=(tag,value,className)=>{const node=document.createElement(tag);node.textContent=value;if(className)node.className=className;return node;};
 function hideTooltip(){$('usage-tooltip').hidden=true;focused?.removeAttribute('aria-describedby');focused=null;}
 function showTooltip(cell,day,rows){hideTooltip();focused=cell;const totals=aggregate(rows),tip=$('usage-tooltip');tip.replaceChildren(text('strong',day.date.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'long',year:'numeric'})),text('span',number(totals.tokens)+' tokens · '+number(totals.requests)+' requests'),text('span',number(totals.input)+' input · '+number(totals.output)+' output'),text('span',number(totals.background)+' tokens in background requests'),text('span',costText(totals)));if(day.key<dateKey(new Date(snapshot.startedAt)))tip.append(text('small','Tracking had not started.'));if(totals.missing||totals.partial)tip.append(text('small','Some requests have incomplete usage reports.'));tip.hidden=false;cell.setAttribute('aria-describedby','usage-tooltip');const box=cell.getBoundingClientRect(),bounds=tip.getBoundingClientRect();tip.style.left=Math.max(12,Math.min(innerWidth-bounds.width-12,box.left-bounds.width/2+box.width/2))+'px';tip.style.top=Math.max(12,Math.min(innerHeight-bounds.height-12,box.top-bounds.height-9))+'px';}
 function render(){if(!snapshot)return;$('usage-calendar').removeAttribute('aria-hidden');hideTooltip();const now=new Date(),period=$('usage-period').value,metric=$('usage-metric').value,records=snapshot.records||[],filtered=records.filter(r=>{const date=new Date(r.timestamp);return period==='all'||period==='year'&&date.getFullYear()===selectedYear||period==='month'&&date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth();}),totals=aggregate(filtered),summary=$('usage-summary');summary.replaceChildren();for(const [value,label]of [[number(totals.tokens),'Total tokens'],[costText(totals),'Estimated API cost'],[number(totals.requests),'Usage reports']]){const card=document.createElement('div');card.append(text('strong',String(value)),text('span',label));summary.append(card);}summary.append(text('p',number(totals.input)+' input · '+number(totals.output)+' output · '+number(totals.background)+' background tokens'+(totals.planTokens?' · '+number(totals.planTokens)+' via ChatGPT plan':''), 'usage-token-detail'));
  $('usage-tracking').textContent='Tracking since '+new Date(snapshot.startedAt).toLocaleDateString()+'. Includes background naming.';
  const byDay=new Map();for(const r of records){const key=dateKey(new Date(r.timestamp));if(!byDay.has(key))byDay.set(key,[]);byDay.get(key).push(r);}const days=calendar(selectedYear),values=days.filter(d=>d.inYear).map(d=>{const t=aggregate(byDay.get(d.key)||[]);return metric==='requests'?t.requests:metric==='cost'?t.cost:t.tokens;}),maximum=Math.max(1e-12,...values),host=$('usage-calendar');host.replaceChildren();host.style.setProperty('--usage-weeks',String(days.length/7));
  const labels=document.createElement('div');labels.className='usage-months';for(let month=0;month<12;month++){const day=days.findIndex(d=>d.inYear&&d.date.getMonth()===month);const label=text('span',new Date(selectedYear,month,1).toLocaleDateString(undefined,{month:'short'}));label.style.gridColumn=String(Math.floor(day/7)+1);labels.append(label);}host.append(labels);
  const weekdays=document.createElement('div');weekdays.className='usage-weekdays';for(const label of ['','Mon','','Wed','','Fri',''])weekdays.append(text('span',label));host.append(weekdays);const grid=document.createElement('div');grid.className='usage-grid';grid.setAttribute('role','group');grid.setAttribute('aria-label',selectedYear+' daily model usage');const today=dateKey(now),start=dateKey(new Date(snapshot.startedAt));let initial=false;
  for(const day of days){if(!day.inYear){const blank=document.createElement('span');blank.className='usage-day is-outside';blank.setAttribute('aria-hidden','true');grid.append(blank);continue;}const rows=byDay.get(day.key)||[],t=aggregate(rows),value=metric==='requests'?t.requests:metric==='cost'?t.cost:t.tokens,cell=document.createElement('button');cell.type='button';cell.className='usage-day';cell.dataset.date=day.key;cell.dataset.level=value?String(Math.max(1,Math.min(4,Math.ceil(Math.sqrt(value/maximum)*4)))):'0';if(day.key<start)cell.classList.add('is-untracked');if(day.key>today)cell.classList.add('is-future');if(metric==='cost'&&t.unpriced)cell.classList.add('is-unpriced');cell.setAttribute('aria-label',day.key+': '+number(t.tokens)+' tokens, '+number(t.requests)+' requests, '+costText(t));cell.tabIndex=!initial&&day.key>=start&&day.key<=today?0:-1;if(cell.tabIndex===0)initial=true;cell.addEventListener('pointerenter',()=>showTooltip(cell,day,rows));cell.addEventListener('pointerleave',hideTooltip);cell.addEventListener('focus',()=>showTooltip(cell,day,rows));cell.addEventListener('blur',hideTooltip);cell.addEventListener('click',()=>cell.focus());grid.append(cell);}
  grid.addEventListener('keydown',event=>{const changes={ArrowUp:-1,ArrowDown:1,ArrowLeft:-7,ArrowRight:7};if(changes[event.key]===undefined)return;const cells=[...grid.querySelectorAll('button')],index=cells.indexOf(document.activeElement),next=cells[Math.max(0,Math.min(cells.length-1,index+changes[event.key]))];if(next){event.preventDefault();cells.forEach(c=>c.tabIndex=-1);next.tabIndex=0;next.focus();}});if(!initial)grid.querySelector('button')?.setAttribute('tabindex','0');host.append(grid);
  $('usage-calendar-caption').textContent=selectedYear+' · '+(metric==='cost'?'Estimated cost':metric==='requests'?'Requests':'Tokens')+' per day';$('usage-empty').hidden=records.length>0;
  const breakdown=$('usage-breakdown');breakdown.replaceChildren();if(totals.models.length){const table=document.createElement('table'),head=document.createElement('thead'),body=document.createElement('tbody'),tr=document.createElement('tr');for(const label of ['Provider / model','Tokens','Estimated cost'])tr.append(text('th',label));head.append(tr);for(const m of totals.models){const row=document.createElement('tr');row.append(text('td',(m.provider==='openai'?'OpenAI':'Anthropic')+' · '+m.model),text('td',number(m.tokens)),text('td',costText(m)));body.append(row);}table.append(head,body);breakdown.append(table);}
  const notices=['ChatGPT plan usage is not billed at the displayed API estimates.','Atlas requests only; earlier usage cannot be recovered.', 'Each activity report can cover several Codex model requests. Reports without token counts are unavailable. Rates checked '+snapshot.pricingDate+'.'];if(totals.unpriced)notices.push(totals.unpriced+' requests have no complete price estimate; known costs are a subtotal.');if(totals.missing||totals.partial)notices.push((totals.missing+totals.partial)+' requests have incomplete token reports; totals may be understated.');$('usage-notes').textContent=notices.join(' ');if(snapshot.rateLimits){const limits=[snapshot.rateLimits.primary,snapshot.rateLimits.secondary].filter(Boolean).map(w=>Math.round(w.usedPercent)+'% used · resets '+new Date(w.resetsAt*1000).toLocaleString());$('usage-notes').textContent+=' Plan limits: '+limits.join('; ');}$('usage-error').hidden=!snapshot.storageError;$('usage-error').textContent=snapshot.storageError||'';
 }
 function loadingCalendar(){
  if(snapshot)return;const host=$('usage-calendar');host.replaceChildren();host.setAttribute('aria-hidden','true');host.style.setProperty('--usage-weeks','53');
  const grid=document.createElement('div');grid.className='usage-grid usage-loading-grid';for(let i=0;i<371;i++){const cell=document.createElement('span');cell.className='usage-day';grid.append(cell);}host.append(grid);$('usage-tracking').textContent='Loading usage…';
 }
 async function load(){const version=++loadVersion;$('usage-activity').setAttribute('aria-busy','true');loadingCalendar();try{if(!bridge?.assistantUsage)throw new Error('API usage is available in the desktop app.');const value=await bridge.assistantUsage();if(version!==loadVersion)return;snapshot=value;const select=$('usage-year'),earliest=Math.min(new Date(snapshot.startedAt).getFullYear(),...snapshot.records.map(r=>new Date(r.timestamp).getFullYear()));select.replaceChildren();for(let year=new Date().getFullYear();year>=earliest;year--){const option=text('option',year);option.value=String(year);select.append(option);}select.value=String(selectedYear);render();}catch(error){if(version!==loadVersion)return;$('usage-error').hidden=false;$('usage-error').textContent=error.message;if(!snapshot)$('usage-tracking').textContent='Usage unavailable';}finally{if(version===loadVersion)$('usage-activity').setAttribute('aria-busy','false');}}
 $('assistant-usage-button').onclick=()=>{$('usage-dialog').showModal();$('usage-dialog').scrollTop=0;if(snapshot)render();void load();};$('usage-close').onclick=()=>{$('usage-dialog').close();hideTooltip();};$('usage-dialog').addEventListener('close',hideTooltip);$('usage-dialog').addEventListener('scroll',hideTooltip,true);$('usage-period').onchange=render;$('usage-metric').onchange=render;$('usage-year').onchange=()=>{selectedYear=Number($('usage-year').value);render();};
 bridge?.onEvent(event=>{if(event.type==='assistant-usage-updated'&&$('usage-dialog').open){clearTimeout(refreshTimer);refreshTimer=setTimeout(load,80);}});
